\label{lem1.1}
For any $a \ge 0$, there is an $f_a$ in $H^2$ such that
\begin{equation}\label{1.6}
\mbox{$\gamma_a = \|L_a \,f_a\|^2$, and $\|f_a\| = 1$}.
\end{equation}

We first note that for any $a \ge 0$, there is $c_a > 0$ such that
\begin{equation}\label{1.7}
a \, \|B f\| \le \mbox{\footnotesize $\displaystyle\frac{1}{2}$} \; \| D f \| + c_a \,\| f \|, \; \mbox{for all $f \in H^2$}.
\end{equation}
Indeed, by (\ref{1.2}) we have $\| Bf \| \le c_* \| f \|_1$, and with the notation above (\ref{1.1}), one has for all $a \ge 0$ a non-negative $\widetilde{c}_a$ such that for all sequences of reals $c_k, k \ge 1$, $(c_* a)^2\, \Sigma_k \, \lambda_k \, c^2_k \le \frac{1}{4} \, \Sigma_k \, \lambda_k^2 \, c_k^2 + \widetilde{c}_a \, \Sigma_k \, c_k^2$, and (\ref{1.7}) follows.

\medskip
As a result of (\ref{1.7}), we see that for fixed $a \ge 0$, for all $f \in H^2$ with $\| f \| = 1$
\begin{equation}\label{1.8}
\|L_a f\| = \| D f + a \, B f\| \ge \| Df \| - a \| B f \| \stackrel{(\ref{1.7})}{\ge} \mbox{\footnotesize $\displaystyle\frac{1}{2}$} \; \| D f \| - c_a.
\end{equation}
Thus, for (\ref{1.5}), when $g_n$ is a minimizing sequence in $H^2$ such that $\| g_n \| = 1$ and $\| L_a \, g_n\|^2 \longrightarrow \gamma_a$, we see by (\ref{1.8}) that $\| D g_n\|$ is bounded. We can then extract a subsequence $g_{n_k}$ converging weakly in $H^2$ to $g_*$, see \cite{Lax02} on p.~104, and strongly in $H^1$ and $H$ to $g_*$, so that $\| D g_*\|^2 = \|  g_*\|^2_2 \le \liminf_k \, \|g_{n_k}\|^2_2$. We then have 
\begin{equation}\label{1.9}
\gamma_a = \lim\limits_k \|L_a \, g_{n_k} \|^2 = \lim\limits_k (\|g_{n_k}\|^2_2 + 2a \langle D g_{n_k}, Bg_{n_k}\rangle + a^2 \|Bg_{n_k}\|^2).
\end{equation}
Now, $Dg_{n_k}$ converges weakly in $H$ to $Dg_*$ and by (\ref{1.2}) $Bg_{n_k}$ converges strongly to $Bg_*$ in $H$, so that $\langle D g_{n_k},Bg_{n_k}\rangle$ tends to $\langle Dg_*, Bg_*\rangle$. Together with the observation above (\ref{1.9}), we see that $\| g_*\| = 1$ and
\begin{equation}\label{1.10}
\gamma_a \ge \| Dg_*\|^2 + 2a \langle Dg_*, Bg_*\rangle + a^2 \|Bg_*\|^2 = \|L_a g_*\|^2.
\end{equation}
The claim (\ref{1.6}) follows with $f_a = g_*$, and Lemma \ref{lem1.1} is proved.

\label{prop1.2}
For $a \ge 0$ and $f_a$ as in \rm{(\ref{1.6})}, one has
\begin{equation}\label{1.11}
\gamma_a \ge (\|f_a \|_2 - a \,\|Bf_a \|)^2 + a \mbox{\footnotesize $\displaystyle\frac{\|Bf_a\|}{\|f_a\|_2}$} \; \| f_a \|_1^4,
\end{equation}
and, see (\ref{1.3}) for notation,
\begin{equation}\label{1.12}
\gamma_a  + 2 a \, c_{**} \, \|f_a\|_1^2 \ge a^2 \|Bf_a\|^2 + \|f_a \|^2_2.
\end{equation}

We first prove (\ref{1.11}). We note that $B$ is antisymmetric, its domain contains $H^1$, and $f_a$ belongs to $H^2$, so that $\langle f_a, Bf_a\rangle = 0$. Hence, for all $a \ge 0$ and $\lambda$ in ${\mathbb R}$, one has
\begin{equation}\label{1.13}
\begin{array}{lcl}
\gamma_a &\!\!\!\! \stackrel{(\ref{1.6})}{=} &\!\!\!\! \| Df_a + a \,Bf_a\|^2 = \|D f_a \|^2 + 2 a \langle (D+ \lambda)\,f_a, Bf_a \rangle + a^2 \,\|Bf_a\|^2
\\[1ex]
&\!\!\!\! \ge &\!\!\!\!  \|D f_a \|^2 - 2 a \,\|(D+ \lambda) \,f_a \| \; \|Bf_a \| + a^2 \,\|Bf_a\|^2
\\[1ex]
&\!\!\!\! = &\!\!\!\!  (\| Df_a \| - a \, \|Bf_a \|)^2 + 2a \, \|Bf_a \| \; (\|Df_a \| - \|(D + \lambda) \,f_a\|).
\end{array}
\end{equation}
Choosing $\lambda = -\langle Df_a, f_a \rangle \stackrel{(\ref{1.1})}{=} \|f_a \|^2_1$ and using $\|f_a\| =1$, we find that
\begin{equation}\label{1.14}
\begin{split}
\|Df_a + \lambda f_a\|^2 & = \|Df_a\|^2 + 2\lambda \, \langle Df_a, f_a \rangle + \lambda^2
\\[1ex]
& = \|f_a \|^2_2 - \|f_a \|_1^4 .
\end{split}
\end{equation}
We can now come back to the last line of (\ref{1.13}), and with $\|Df_a\| = \|f_a\|_2$ find:
\begin{equation}\label{1.15}
\begin{split}
\gamma_a & \ge \|f_a\|_2 - a \, \|Bf_a\|)^2 + 2 a \, \| Bf_a \| \; \|f_a\|^4_1 \, / \, \{\|f_a\|_2 + (\|f_a\|^2_2 - \|f_a\|_1^4)^{1/2}\}
\\[0.5ex]
& \ge (\|f_a\|_2 - a\,\|Bf_a\|)^2 + a \; \mbox{\footnotesize $\displaystyle\frac{\| Bf_a\|}{\|f_a\|_2}$} \; \|f_a\|^4_1 ,
\end{split}
\end{equation}
and this proves (\ref{1.11}).  As for (\ref{1.12}), we note using (\ref{1.3}) in the second line that
\begin{equation}\label{1.16}
\begin{split}
\gamma_a & \stackrel{(\ref{1.6})}{=} \| Df_a + a\, Bf_a\|^2 = \|f_a\|^2_2 + a^2 \, \|Bf_a\|^2 + 2a \langle Df_a, Bf_a \rangle
\\[0.5ex]
& \stackrel{(\ref{1.3})}{\ge} \|f_a\|^2_2 + a^2 \,\|Bf_a\|^2 - 2a \, c_{**} \|f_a \|^2_1,
\end{split}
\end{equation}
and the claim (\ref{1.12}) follows. This completes the proof of Proposition \ref{prop1.2}.

\label{theo1.3}
The following two conditions are equivalent
\begin{align}
& \lim\limits_{a \longrightarrow \infty} \; \gamma_a = \infty, \label{1.17}
\\[1ex]
& \mbox{the only $f$ in $H^1$ such that $Bf = 0$ is $f = 0$}. \label{1.18}
\end{align}
Moreover, if {\rm (\ref{1.17})} (or equivalently {\rm  (\ref{1.18})}) does not hold, then
\begin{equation}\label{1.19}
\sup\limits_{a \ge 0} \; \gamma_a < \infty.
\end{equation}

We first show that
\begin{equation}\label{1.20}
\mbox{if $\liminf\limits_{a \longrightarrow \infty} \; \gamma_a < \infty$, then there exists $f_*$ in $H^1 \backslash \{0\}$ such that $Bf_* = 0$}.
\end{equation}
To this end, assuming that $\liminf_{a \longrightarrow \infty} \gamma_a < \infty$, we consider $a_n \longrightarrow \infty$ such that $\lim_n \gamma_{a_n} = \gamma_* < \infty$. As a first step we note that necessarily
\begin{equation}\label{1.21}
\|f_{a_n}\|_2 = o(a_n), \; \mbox{as $n \longrightarrow \infty$}.
\end{equation}
Indeed, otherwise, by (\ref{1.11}), extracting a subsequence still denoted by $a_n$, with at least linear growth in $a_n$, we would have $\|f_{a_n}\|_2 \sim a_n \|Bf_{a_n}\|$, and by (\ref{1.11}), $\|f_{a_n}\|_1$ would be uniformly bounded. However, this would contradict (\ref{1.12}). Hence, (\ref{1.21}) holds.

\medskip
Since (\ref{1.21}) holds, there are two possibilities:

\medskip
Either both $\|f_{a_n}\|_2$ and $a_n \|Bf_{a_n}\|$ are uniformly bounded.

\medskip
In this case, see \cite{Lax02} on p.~104, we can extract a subsequence, still denoted by $a_n$, such that $f_{a_n}$ converges weakly in $H^2$, and hence strongly in $H^1$ to $f_*$, and hence $\|Bf_*\| = \lim_n \|Bf_{a_n}\| = 0$. So $\|f_*\| = 1$ and the conclusion of (\ref{1.20}) holds.

\medskip
Or, along a subsequence, still denoted by $a_n$, both $\|f_{a_n}\|_2$ and $a_n \|Bf_{a_n}\|$ tend to infinity and are $o(a_n)$. In this case, $\|Bf_{a_n}\|$ tends to $0$, and by (\ref{1.11}) the sequence $\|f_{a_n}\|_1$ remains bounded. We can then find, by the same reference as above, a further subsequence, still denoted by $a_n$, and $f_*$ in $H^1$ with $\|f_*\| = 1$, which is a weak limit on $H^1$ and a strong limit in $H$ of $f_{a_n}$. Then, for any $\varphi$ finite linear combination of the eigenfunctions $\varphi_k, k \ge 1$, see above (\ref{1.1}), we find that
\begin{equation}\label{1.22}
\begin{array}{l}
\langle Bf_{a_n}, \varphi\rangle \underset{n}{\longrightarrow} 0, \; \mbox{and}
\\
\langle Bf_{a_n}, \varphi \rangle = - \langle f_{a_n}, B \varphi \rangle \underset{n}{\longrightarrow} - \langle f_*, B \varphi\rangle = \langle Bf_*, \varphi \rangle.
\end{array}
\end{equation}
This shows that $\langle Bf_*, \varphi \rangle = 0$, for all $\varphi$ as above, so that $f_*$ satisfies the conclusion of (\ref{1.20}). This completes the proof of (\ref{1.20}), and shows by contradiction that (\ref{1.18}) implies (\ref{1.17}).

\medskip
We will now prove that
\begin{equation}\label{1.23}
\mbox{if there is $f_* \not= 0$ in $H^1$ with $Bf_* = 0$, then $\sup\limits_{a \ge 0} \gamma_a < \infty$}.
\end{equation}
This will complete the proof of the equivalence of (\ref{1.17}) and (\ref{1.18}), and the fact if (\ref{1.18}) (or (\ref{1.17})) does not hold then (\ref{1.19}) holds. Theorem \ref{theo1.3} will then be proved.

\medskip
We thus show (\ref{1.23}). Without loss of generality, we can assume that $\|f_*\| = 1$. Set $f_a(t) = Q^a_t \, f_*$, for $t \ge 0$ (see (\ref{1.4}) for notation). By \cite{{ConsKiseRyzhZlat08}} on p.~651, we have for $t \ge 0$
\begin{equation}\label{1.24}
\langle f_a(t), f_*\rangle = 1 + \displaystyle\int^t_0 \langle D f_a(s), f_*\rangle ds \ge 1 - \mbox{\footnotesize $\displaystyle\frac{1}{2}$} \;\displaystyle\int^t_0 (\|f_a(s)\|_1^2 + \|f_*\|^2_1) \,ds,
\end{equation}
as well as
\begin{equation}\label{1.25}
\displaystyle\int^\infty_0 \|f_a(s) \|^2_1 \, ds \le \mbox{\footnotesize $\displaystyle\frac{1}{2}$} \,.
\end{equation}
Thus, choosing $t \le \tau_* = (2 \|f_*\|^2_1)^{-1}$, we see that
\begin{equation}\label{1.26}
\langle f_a(t), f_* \rangle \ge \mbox{\footnotesize $\displaystyle\frac{1}{2}$}, \; \mbox{for $0 \le t \le \tau_*$}.
\end{equation}
Since $f_* \in H^1$, $f_a(t)$ belongs to $L^2([0,T], H^2) \cap C([0,T], H^1)$, for any $T > 0$, by Theorem 2.1 of \cite{ConsKiseRyzhZlat08}, and we have, see (15) on p.~421 of \cite{Lax02} (or also (35) of \cite{EberLorl26})
\begin{equation}\label{1.27}
L_a \,\Big(\displaystyle\int^t_0 f_a(s) \,ds\Big) = f_a(t) - f_a(0) = f_a(t) - f_*, \; \mbox{for $t \ge 0$}.
\end{equation}
Hence, by (\ref{1.5}), we have
\begin{equation}\label{1.28}
\gamma_a^{1/2} \,\Big\| \displaystyle\int^t_0 f_a(s)\,ds\Big\| \le \| f_a(t) - f_*\| \le 2, \; \mbox{for $t > 0$}.
\end{equation}
On the other hand, by (\ref{1.26}), $\langle \int^t_0 f_a (s)\,ds, f_*\rangle \ge t/2$, for $0 \le t \le \tau_*$, so that
\begin{equation}\label{1.29}
\Big\|\displaystyle\int^t_0 f_a(s)\, ds\Big\| \ge t/2, \; \mbox{for $0 \le t \le \tau_*$}.
\end{equation}
Inserting this inequality into (\ref{1.28}), and recalling the definition of $\tau_*$ above (\ref{1.26}), we find that for all $a \ge 0$,
\begin{equation}\label{1.30}
\gamma_a^{1/2} \le 4/\tau_* = 8 \, \|f_*\|^2_1 .
\end{equation}
This proves (\ref{1.23}), and as already explained, completes the proof of Theorem \ref{theo1.3}.

\label{theo1.4}
The following two conditions are equivalent:
\begin{align}
& \lim\limits_{a \longrightarrow \infty} \overline{\tau}_{\rm rel}\, \big((Q^a_t)_{t \ge 0}\big) = 0, \label{1.35}
\\[1ex]
& \mbox{the only $f$ in $H^1$ such that $Bf = 0$ is $f = 0$}. \label{1.36}
\end{align}
Moreover, if {\rm (\ref{1.35})} (or equivalently {\rm (\ref{1.36})}) does not hold, then
\begin{equation}\label{1.37}
\inf\limits_{a \ge 0} \overline{\tau}_{\rm rel} \,\big((Q^a_t)_{t \ge 0}\big) > 0.
\end{equation}
